"""Evaluate requests against a collection of evidence records."""

import json


def _canonical_json(value):
    """Return a stable JSON representation used solely for value comparison."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )


def evaluate(request, evidence, policy):
    """Evaluate one request without modifying any supplied object."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)

    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and not record.get("verified", False):
            continue

        record_conditions = record.get("conditions", {})
        if any(
            name not in record_conditions
            or record_conditions[name] != request_conditions[name]
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = {
        source_id
        for record in eligible
        for source_id in record.get("supersedes", [])
        if source_id != record.get("source")
    }
    eligible = [
        record for record in eligible if record.get("source") not in superseded
    ]

    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record.get("source") for record in eligible)
    canonical_values = {_canonical_json(record.get("value")) for record in eligible}
    if len(canonical_values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = eligible[0].get("value")
    return {
        "status": "unsupported" if value is False else "supported",
        "value": value,
        "sources": sources,
        "unknowns": [],
    }

